    if (!CIVS.includes(body.civ)) return { ok: false, error: "Unknown civilisation" };
    const match2 = await db.insertMatch({
      code: makeCode(rng),
      white_id: userId,
      black_id: null,
      white_civ: body.civ,
      black_civ: null,
      state: null,
      status: "open",
      winner: null,
      rated: true,
      updated_at: new Date(now).toISOString()
    });
